begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('f5030000-0000-4000-8000-000000000001','operational-corrections@example.test');
insert into public.workspaces(id,name) values('f5030000-0000-4000-8000-000000000002','Synthetic operational corrections');
insert into public.workspace_users(workspace_id,user_id,role) values('f5030000-0000-4000-8000-000000000002','f5030000-0000-4000-8000-000000000001','admin');
insert into public.cycles(id,workspace_id,year,name,starts_on,closes_on,status) values('f5030000-0000-4000-8000-000000000003','f5030000-0000-4000-8000-000000000002',2026,'Synthetic 2026','2026-01-01','2026-12-15','active');
insert into public.members(id,workspace_id,display_name) values('f5030000-0000-4000-8000-000000000004','f5030000-0000-4000-8000-000000000002','Synthetic member');
insert into public.cycle_members(id,workspace_id,cycle_id,member_id,monthly_quota) values('f5030000-0000-4000-8000-000000000005','f5030000-0000-4000-8000-000000000002','f5030000-0000-4000-8000-000000000003','f5030000-0000-4000-8000-000000000004',100000);
set local natillera.civil_today='2026-10-16';
set local role authenticated;
set local request.jwt.claim.sub='f5030000-0000-4000-8000-000000000001';
select public.create_bank_account('f5030000-0000-4000-8000-000000000003','Synthetic operations bank','','');
select public.record_bank_opening('f5030000-0000-4000-8000-000000000003',(select id from public.bank_accounts where display_name='Synthetic operations bank'),'ops-opening','2026-01-01',1000000,'synthetic opening');
select public.record_internal_liquidity_transfer('f5030000-0000-4000-8000-000000000003','ops-cash','2026-01-01','bank',(select id from public.bank_accounts where display_name='Synthetic operations bank'),'cash',null,500000,'synthetic cash');
select public.register_savings_contribution('f5030000-0000-4000-8000-000000000005','ops-savings',100000,'2026-09-01',2026,9,'bank_transfer','manual');
create temporary table ops_loan as select id from public.create_loan_contract('f5030000-0000-4000-8000-000000000003','ops-loan','f5030000-0000-4000-8000-000000000004',null,null,60000,'fixed_interest','MONTHLY_FIXED',0.05,2,'2026-08-01');
select public.confirm_loan_disbursement((select id from ops_loan),'ops-disburse','2026-08-01');
create temporary table ops_cash_before as select sum(amount) amount from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='cash';
select public.record_loan_payment((select id from ops_loan),'ops-payment','2026-09-01',11500,10000,1500,'regular');
select lives_ok($$select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-payment'),'ops-undo-pay','2026-09-01','Wrong payment')$$,'payment can be reversed');
select is((select status from public.loan_payments where idempotency_key='ops-payment'),'reversed','payment status is reversed');
select is((select coalesce(sum(principal_paid+interest_paid),0) from public.loan_schedule_progress where loan_id=(select id from ops_loan)),0::numeric,'applications no longer mark quota paid');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='cash'),(select amount from ops_cash_before),'cash returns exactly to prior balance');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='loans_receivable'),60000::numeric,'principal is restored');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='admin_payable'),0::numeric,'commission restored');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='member_loan_profit_fund'),0::numeric,'loan profit restored');
select lives_ok($$select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-payment'),'ops-undo-pay','2026-09-01','Wrong payment')$$,'exact retry is idempotent');
select is((select count(*) from public.financial_operations where idempotency_key='ops-undo-pay'),1::bigint,'one reversal after retry');
select throws_ok($$select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-payment'),'ops-undo-pay','2026-09-01','Changed')$$,'P0001','La clave de idempotencia del reverso ya existe con otro contenido.','changed retry rejected');
create temporary table ops_quote as select public.quote_loan_prepayment((select id from ops_loan),'2026-09-02') q;
select public.confirm_loan_prepayment((select id from ops_loan),'ops-full','2026-09-02',(select q->>'quote_hash' from ops_quote));
select is((select status from public.loan_contracts where id=(select id from ops_loan)),'paid','full payment closes loan');
select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-full'),'ops-undo-full','2026-09-02','Wrong full payment');
select is((select status from public.loan_contracts where id=(select id from ops_loan)),'active','full payment reversal reopens loan');
select is((select count(*) from public.loan_schedules where loan_id=(select id from ops_loan) and status='cancelled'),0::bigint,'full payment reversal restores schedule');
select public.record_loan_payment((select id from ops_loan),'ops-older','2026-09-03',1000,1000,0,'regular');
select public.record_loan_payment((select id from ops_loan),'ops-newer','2026-09-04',1000,1000,0,'regular');
select throws_ok($$select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-older'),'ops-undo-old','2026-09-04','Wrong order')$$,'P0001','Primero revierta los cobros posteriores de este prestamo.','later dependent payment must be resolved first');
select throws_ok($$select public.reverse_financial_operation((select operation_id from public.loan_payments where idempotency_key='ops-newer'),'ops-invalid-date','2026-09-01','Wrong date')$$,'P0001','Fecha de reverso invalida.','cannot reverse before original');
select public.create_polla_activity('f5030000-0000-4000-8000-000000000003',2026,9,'Synthetic prize');
select public.register_polla_contribution((select id from public.polla_activities where name='Synthetic prize'),'f5030000-0000-4000-8000-000000000005','ops-polla',10000,'2026-09-01');
create temporary table ops_prize as select id from public.award_polla_prize_to_capital((select id from public.polla_activities where name='Synthetic prize'),'f5030000-0000-4000-8000-000000000005','ops-prize',10000,'2026-09-01');
select throws_ok($$select public.reverse_financial_operation((select operation_id from public.polla_contributions where idempotency_key='ops-polla'),'ops-undo-contribution-early','2026-09-01','Mistake')$$,'P0001','Primero revierta el premio de esta polla antes de retirar sus aportes.','cannot remove funding from active prize');
select lives_ok($$select public.reverse_polla_prize((select id from ops_prize),'ops-undo-prize','2026-09-01','Wrong winner')$$,'credited prize reversed atomically');
select is((select status from public.polla_prizes where id=(select id from ops_prize)),'reversed','prize removed from active list');
select ok((select reversed_at is not null from public.member_capital_credits where prize_id=(select id from ops_prize)),'capital credit reversed without deleting trace');
select is((select status from public.polla_activities where name='Synthetic prize'),'open','activity reopens');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='polla_pool'),(-10000)::numeric,'full prize returns to pool');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='savings_liability'),(-100000)::numeric,'winner capital returns to previous amount');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='admin_payable'),0::numeric,'prize commission undone');
select lives_ok($$select public.reverse_polla_prize((select id from ops_prize),'ops-undo-prize','2026-09-01','Wrong winner')$$,'credited prize retry does not duplicate reversals');
select is((select count(*) from public.financial_operations where idempotency_key in ('ops-undo-prize','ops-undo-prize:capital')),2::bigint,'exactly two component reversals');
select throws_ok($$select public.reverse_polla_prize((select id from ops_prize),'ops-prize-again','2026-09-01','Again')$$,'P0001','El premio ya fue revertido.','second distinct reversal blocked');
select throws_ok($$select public.cancel_polla_activity((select id from public.polla_activities where name='Synthetic prize'),'ops-cancel-early','Mistake')$$,'P0001','Primero revierta el premio y los aportes de esta polla.','cancel waits for contribution reversals');
select public.reverse_financial_operation((select operation_id from public.polla_contributions where idempotency_key='ops-polla'),'ops-undo-polla','2026-09-01','Wrong contribution');
select is((select status from public.polla_contributions where idempotency_key='ops-polla'),'reversed','contribution state restored');
select lives_ok($$select public.cancel_polla_activity((select id from public.polla_activities where name='Synthetic prize'),'ops-cancel','Mistake')$$,'empty activity cancelled');
select is((select count(*) from public.polla_activities where cycle_id='f5030000-0000-4000-8000-000000000003' and cancelled_at is not null),1::bigint,'cancelled activity retained outside active list');
select lives_ok($$select public.create_polla_activity('f5030000-0000-4000-8000-000000000003',2026,9,'Synthetic prize')$$,'same activity name can be created again');
select public.create_polla_activity('f5030000-0000-4000-8000-000000000003',2026,7,'Synthetic cut A');
select public.create_polla_activity('f5030000-0000-4000-8000-000000000003',2026,8,'Synthetic cut B');
select public.register_polla_contribution((select id from public.polla_activities where name='Synthetic cut A'),'f5030000-0000-4000-8000-000000000005','ops-cut-fund-a',10000,'2026-09-01');
select public.register_polla_contribution((select id from public.polla_activities where name='Synthetic cut B'),'f5030000-0000-4000-8000-000000000005','ops-cut-fund-b',10000,'2026-09-01');
create temporary table ops_cut_a as select id from public.award_polla_prize((select id from public.polla_activities where name='Synthetic cut A'),'f5030000-0000-4000-8000-000000000005','ops-cut-a',10000,'2026-09-01');
create temporary table ops_cut_b as select id from public.award_polla_prize_to_capital((select id from public.polla_activities where name='Synthetic cut B'),'f5030000-0000-4000-8000-000000000005','ops-cut-b',10000,'2026-09-02');
reset role;
update public.polla_prizes set legacy_id=id::text,legacy_payment_status='historical_payment_unverified' where id in ((select id from ops_cut_a),(select id from ops_cut_b));
insert into public.legacy_operational_import_batches(id,workspace_id,cycle_id,json_sha256,csv_sha256,payload_sha256,status,counts,totals)
 values('f5030000-0000-4000-8000-000000000006','f5030000-0000-4000-8000-000000000002','f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),repeat('c',64),'imported','{"prizes":2,"loans":0}','{"prizesGross":20000}');
insert into public.legacy_operational_import_mappings(workspace_id,cycle_id,batch_id,source_type,source_id,target_table,target_id,payload)
 select 'f5030000-0000-4000-8000-000000000002','f5030000-0000-4000-8000-000000000003','f5030000-0000-4000-8000-000000000006','prize',p.id::text,'polla_prizes',p.id,jsonb_build_object('grossAmount',p.gross_amount) from public.polla_prizes p where id in ((select id from ops_cut_a),(select id from ops_cut_b));
set local role authenticated;
create temporary table ops_cut_preview as select public.preview_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),'2026-10-01') q;
create temporary table ops_cut_cash as select sum(amount) amount from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='cash';
select is((select (q->>'credit_to_add')::numeric from ops_cut_preview),5000::numeric,'cut adds only missing credit');
select is((select (q->>'credits_preserved')::numeric from ops_cut_preview),5000::numeric,'cut preserves existing credit');
select throws_ok($$select public.confirm_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),'2026-10-01','stale','Owner confirmed')$$,'P0001','El corte cambio; vuelva a calcular antes de confirmar.','stale cut is rejected');
select lives_ok($$select public.confirm_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),'2026-10-01',(select q->>'preview_hash' from ops_cut_preview),'Owner confirmed')$$,'cut confirmation is atomic');
select is((select effective_date from public.member_capital_credits where prize_id=(select id from ops_cut_a)),'2026-10-01'::date,'missing credit uses approved cutoff');
select is((select effective_date from public.member_capital_credits where prize_id=(select id from ops_cut_b)),'2026-09-02'::date,'existing credit date preserved');
select is((select sum(amount) from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' and account='cash'),(select amount from ops_cut_cash),'cut creates no fictitious cash');
select is((select count(*) from public.polla_prizes where id in ((select id from ops_cut_a),(select id from ops_cut_b)) and legacy_payment_status='paid_verified'),2::bigint,'source prizes are consolidated');
select lives_ok($$select public.confirm_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),'2026-10-01',(select q->>'preview_hash' from ops_cut_preview),'Owner confirmed')$$,'cut confirmation retry creates no additional credit');
select is((select count(*) from public.member_capital_credits where prize_id in ((select id from ops_cut_a),(select id from ops_cut_b))),2::bigint,'one credit per source prize');
select ok(not has_function_privilege('authenticated','public.ops_reverse_prize_component(uuid,text,date,text,uuid)','execute'),'coordinated internal helper is private');
select ok(not has_function_privilege('authenticated','public.ops_reverse_financial_operation_base(uuid,text,date,text)','execute'),'base reversal cannot bypass coordination');
select throws_ok($$select public.reverse_financial_operation((select id from public.financial_operations where idempotency_key='ops-undo-prize'),'ops-undo-undo','2026-09-01','Undo undo')$$,'P0001','No se reversa un reverso.','coordinated reversal cannot itself be reversed');
select throws_ok($$select public.preview_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('d',64),repeat('b',64),'2026-10-01')$$,'P0001','Los archivos no corresponden al lote registrado en este ciclo.','unmatched backup cannot consolidate');
create temporary table ops_foreign_target as select operation_id from public.loan_payments where idempotency_key='ops-newer';
set local request.jwt.claim.sub='f5030000-0000-4000-8000-000000000099';
select throws_ok($$select public.reverse_financial_operation((select operation_id from ops_foreign_target),'ops-cross-user','2026-09-04','Unauthorized')$$,'P0001','No tiene permiso sobre este workspace.','server rejects known operation ID from unrelated user');
select throws_ok($$select public.preview_operational_cut('f5030000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64),'2026-10-01')$$,'P0001','No tiene permiso sobre este workspace.','unrelated user cannot inspect baseline');
set local request.jwt.claim.sub='f5030000-0000-4000-8000-000000000001';
select is((select count(*) from (select operation_id from public.ledger_entries where cycle_id='f5030000-0000-4000-8000-000000000003' group by operation_id having sum(amount)<>0) s),0::bigint,'all original and inverse ledger entries balance');
select * from finish();
rollback;
